package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.gcd method.
 * Aiming for maximum branch and line coverage.
 */
public class MathUtils_gcd_TriageGen0Test {















    @Test
    public void testGcdBinaryBranching() {
        // Test B2/B3: t logic
        // If u was odd, t = v. If u was even, t = -(u/2).

        // Case: u is odd, v is even
        // u=-3, v=-2. k=0. t = v = -2.
        // loop: t=-2 -> t becomes -1 (cast out 2s). t is negative, so v = -1.
        // t = (v-u)/2 = (-1 - (-3))/2 = 1.
        // loop: t=1 -> t is positive, so u = -1.
        // t = (v-u)/2 = (-1 - (-1))/2 = 0. loop ends.
        // return -u * 1 = 1.
        assertEquals(1, MathUtils.gcd(3, 2));

        // Case: u is even, v is odd
        // u=-2, v=-3. k=0. t = -(u/2) = 1.
        // loop: t=1 -> t is positive, u = -1.
        // t = (v-u)/2 = (-3 - (-1))/2 = -1.
        // loop: t=-1 -> t is negative, v = -1.
        // t = (v-u)/2 = (-1 - (-1))/2 = 0. loop ends.
        // return -u * 1 = 1.
        assertEquals(1, MathUtils.gcd(2, 3));
    }


}

