/**
 * Unit tests for MathUtils.gcd method.
 * Aiming for maximum branch and line coverage.
 */
public class MathUtils_gcd_TriageGen0Test {

















    @Test
    public void testGcdMinIntNonZero() {
        // If u is MIN_VALUE, it's not 0, so it proceeds to make u negative (it already is)
        // gcd(MIN_VALUE, 1)
        // u = -2147483648, v = -1. k = 0.
        // t = (u is even) ? v : -(u/2) -> t = -1073741824.
        // This tests the path where u is MIN_VALUE but not 0.
        int result = MathUtils.gcd(Integer.MIN_VALUE, 1);
        assertEquals(1, result);
    }
}
